create extension if not exists pgcrypto;
create table projects(id uuid primary key default gen_random_uuid(),name text not null,slug text not null unique,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table series(id uuid primary key default gen_random_uuid(),project_id uuid not null references projects(id) on delete cascade,name text not null,international_name text,bible_version int not null default 1,target_age_min int not null default 4,target_age_max int not null default 9,default_fps int not null default 24,default_width int not null default 1920,default_height int not null default 1080,status text not null default 'DRAFT',created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check(target_age_min<=target_age_max));
create table seasons(id uuid primary key default gen_random_uuid(),series_id uuid not null references series(id) on delete cascade,season_number int not null check(season_number>0),title text,status text not null default 'DRAFT',unique(series_id,season_number));
create table episodes(id uuid primary key default gen_random_uuid(),season_id uuid not null references seasons(id) on delete cascade,episode_number int not null check(episode_number>0),title text not null,target_duration_sec int not null check(target_duration_sec>0),language text not null default 'hu',story_brief text,script_version int not null default 1,status text not null default 'DRAFT',estimated_cost_usd numeric not null default 0 check(estimated_cost_usd>=0),actual_cost_usd numeric not null default 0 check(actual_cost_usd>=0),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(season_id,episode_number));
create table scenes(id uuid primary key default gen_random_uuid(),episode_id uuid not null references episodes(id) on delete cascade,scene_number int not null check(scene_number>0),title text,story_summary text,start_continuity_state jsonb not null default '{}'::jsonb,end_continuity_state jsonb not null default '{}'::jsonb,unique(episode_id,scene_number));
create table assets(id uuid primary key default gen_random_uuid(),project_id uuid not null references projects(id) on delete cascade,kind text not null,storage_provider text not null,object_key text not null,mime_type text,size_bytes bigint,sha256 text,metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),unique(storage_provider,object_key));
create table shots(id uuid primary key default gen_random_uuid(),scene_id uuid not null references scenes(id) on delete cascade,shot_number int not null check(shot_number>0),schema_version text not null default '1.0',status text not null default 'DRAFT',duration_sec numeric not null check(duration_sec>0),shot_document jsonb not null,current_preview_asset_id uuid references assets(id),current_final_asset_id uuid references assets(id),qc_score numeric check(qc_score between 0 and 1),estimated_cost_usd numeric not null default 0 check(estimated_cost_usd>=0),actual_cost_usd numeric not null default 0 check(actual_cost_usd>=0),revision int not null default 1 check(revision>0),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(scene_id,shot_number,revision));
create table render_jobs(id uuid primary key default gen_random_uuid(),shot_id uuid not null references shots(id) on delete cascade,render_type text not null,status text not null default 'QUEUED',worker_type text not null,provider text,attempt int not null default 1,max_attempts int not null default 3,input_snapshot jsonb not null,output_asset_id uuid references assets(id),started_at timestamptz,finished_at timestamptz,gpu_seconds numeric,cost_usd numeric not null default 0,error_code text,error_message text,created_at timestamptz not null default now());
create table qc_results(id uuid primary key default gen_random_uuid(),shot_id uuid not null references shots(id) on delete cascade,render_job_id uuid references render_jobs(id) on delete cascade,check_type text not null,status text not null,score numeric check(score between 0 and 1),details jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create index shots_scene_status_idx on shots(scene_id,status);
create index render_jobs_status_created_idx on render_jobs(status,created_at);
create index qc_results_shot_status_idx on qc_results(shot_id,status);
alter table projects enable row level security;
alter table series enable row level security;
alter table seasons enable row level security;
alter table episodes enable row level security;
alter table scenes enable row level security;
alter table assets enable row level security;
alter table shots enable row level security;
alter table render_jobs enable row level security;
alter table qc_results enable row level security;
